import base64
import subprocess

items = _items
if not items:
    raise Exception("Aucun fichier recu")

item = items[0]
json_data = item.get('json') or {}
video_base64 = json_data.get('videoBase64')
if video_base64 is None:
    raise Exception("Champ 'videoBase64' introuvable (noeud 'To Base64' manquant ou mal configure)")

raw = base64.b64decode(video_base64)

proc = subprocess.run(
    ['ffmpeg', '-y', '-f', 'avi', '-i', 'pipe:0',
     '-frames:v', '500', '-f', 'image2pipe', '-vcodec', 'mjpeg', 'pipe:1'],
    input=raw,
    stdout=subprocess.PIPE,
    stderr=subprocess.PIPE,
    timeout=120
)

if proc.returncode != 0:
    stderr_tail = proc.stderr.decode('utf-8', errors='replace')[-1500:]
    raise Exception("ffmpeg a echoue (code {}): {}".format(proc.returncode, stderr_tail))

stream = proc.stdout
SOI = b'\xff\xd8'
EOI = b'\xff\xd9'
frames = []
start = 0
while True:
    soi_idx = stream.find(SOI, start)
    if soi_idx == -1:
        break
    eoi_idx = stream.find(EOI, soi_idx + 2)
    if eoi_idx == -1:
        break
    eoi_idx += 2
    frames.append(stream[soi_idx:eoi_idx])
    start = eoi_idx

if not frames:
    stderr_tail = proc.stderr.decode('utf-8', errors='replace')[-1500:]
    raise Exception("ffmpeg n'a produit aucune frame pour ce fichier. Stderr: " + stderr_tail)

results = []
for idx, frame_bytes in enumerate(frames, start=1):
    file_name = 'frame_{:04d}.jpg'.format(idx)
    results.append({
        'json': {
            'frameNumber': idx,
            'fileName': file_name,
            'mimeType': 'image/jpeg',
            'sizeBytes': len(frame_bytes)
        },
        'binary': {
            'data': {
                'data': base64.b64encode(frame_bytes).decode('ascii'),
                'mimeType': 'image/jpeg',
                'fileName': file_name
            }
        }
    })

return results
